INSERT INTO `qlo_pulse_crm_segment` VALUES (1,'first_timers','First-timers','Guests with exactly one completed stay','{\"match\":\"all\",\"rules\":[{\"field\":\"stays\",\"op\":\"eq\",\"value\":1},{\"field\":\"blacklisted\",\"op\":\"eq\",\"value\":0}]}',1,1,0,NULL,0,NULL,'2026-09-14 10:02:49','2026-09-14 10:02:49',1),(2,'repeat','Repeat guests','Three or more stays','{\"match\":\"all\",\"rules\":[{\"field\":\"stays\",\"op\":\"gte\",\"value\":3},{\"field\":\"blacklisted\",\"op\":\"eq\",\"value\":0}]}',1,1,0,NULL,0,NULL,'2026-09-14 10:02:49','2026-09-14 10:02:49',1),(3,'lapsed_12m','Lapsed 12 months','Stayed before but nothing in the last 365 days','{\"match\":\"all\",\"rules\":[{\"field\":\"stays\",\"op\":\"gte\",\"value\":1},{\"field\":\"last_stay_days\",\"op\":\"gte\",\"value\":365},{\"field\":\"blacklisted\",\"op\":\"eq\",\"value\":0}]}',1,1,0,NULL,0,NULL,'2026-09-14 10:02:49','2026-09-14 10:02:49',1),(4,'corporate','Corporate travellers','Attached to a company account','{\"match\":\"all\",\"rules\":[{\"field\":\"has_company\",\"op\":\"eq\",\"value\":1},{\"field\":\"blacklisted\",\"op\":\"eq\",\"value\":0}]}',1,1,0,NULL,0,NULL,'2026-09-14 10:02:49','2026-09-14 10:02:49',1),(5,'high_spenders','High spenders','Lifetime revenue above 1,500,000 naira','{\"match\":\"all\",\"rules\":[{\"field\":\"lifetime_revenue\",\"op\":\"gte\",\"value\":1500000},{\"field\":\"blacklisted\",\"op\":\"eq\",\"value\":0}]}',1,1,0,NULL,0,NULL,'2026-09-14 10:02:49','2026-09-14 10:02:49',1),(6,'detractors','Detractors needing follow-up','Last NPS 6 or below','{\"match\":\"all\",\"rules\":[{\"field\":\"nps_band\",\"op\":\"eq\",\"value\":\"detractor\"}]}',1,1,0,NULL,0,NULL,'2026-09-14 10:02:49','2026-09-14 10:02:49',1),(7,'birthdays_30d','Upcoming birthdays','Birthday inside the next 30 days','{\"match\":\"all\",\"rules\":[{\"field\":\"birthday_in_days\",\"op\":\"lte\",\"value\":30},{\"field\":\"opt_in_email\",\"op\":\"eq\",\"value\":1}]}',1,1,0,NULL,0,NULL,'2026-09-14 10:02:49','2026-09-14 10:0