INSERT INTO `qlo_pulse_crm_survey` VALUES (1,'in_stay','In-stay check','in_stay','You are on night two with us. Thirty seconds, and we can still fix anything that is not right.','Thank you. If you flagged something, a duty manager will call your room shortly.',6,7,1,'2026-09-14 10:02:49','2026-09-14 10:02:49',1),(2,'post_stay','Post-stay satisfaction','post_stay','Thank you for staying with us. Your answers go straight to the general manager.','Thank you — this is read every morning at our stand-up.',6,30,1,'2026-09-14 10:02:49','2026-09-14 10:02:49',1),(3,'fnb','Restaurant and bar','fnb','How was your meal with us today?','Thank you. Chef reads every one of these.',6,14,1,'2026-09-14 10:02:49','2026-09-14 10:02:49',1);
