INSERT INTO `qlo_pulse_pr_relief` VALUES (1,'NG','RENT','Rent relief','capped_percent',20.000,0.000000,500000.000000,'DECLARED','annual',1,'RENT','20% of annual rent actually paid, capped at N500,000. Only where the employee has declared the rent and the evidence is on file. Nigeria Tax Act 2025.',10,'2026-01-01',NULL,1),(2,'NG','PENSION','Pension contribution (employee)','percent_of',0.000,0.000000,NULL,'CONTRIB:PENSION','annual',0,NULL,'Statutory employee pension contribution is deducted before tax.',20,'2026-01-01',NULL,1),(3,'NG','NHF','National Housing Fund contribution','percent_of',0.000,0.000000,NULL,'CONTRIB:NHF','annual',0,'NHF_CONSENT','Deductible before tax only where the employee has actually contributed — NHF is voluntary for private-sector employees.',30,'2026-01-01',NULL,1),(4,'NG','LIFE','Life assurance premium','percent_of',100.000,0.000000,NULL,'DECLARED','annual',1,'LIFE','Premium on the life of the employee or spouse, evidenced by the policy and receipts.',40,'2026-01-01',NULL,1),(5,'NG','MORTGAGE','Mortgage interest (owner-occupied)','percent_of',100.000,0.000000,NULL,'DECLARED','annual',1,'MORTGAGE','Interest on a loan for an owner-occupied home, evidenced by the lender statement.',50,'2026-01-01',NULL,1),(6,'NG','CRA','Consolidated Relief Allowance','greater_of',20.000,200000.000000,NULL,'GROSS','annual',0,NULL,'ABOLISHED from 1 January 2026. Retained with an effective-to date so a back-dated 2025 recalculation still works: higher of N200,000 or 1% of gross, plus 20% of gross.',10,'2011-06-14','2025-12-31',1),(7,'NG','PENSION','Pension contribution (employee)','percent_of',0.000,0.000000,NULL,'CONTRIB:PENSION','annual',0,NULL,'Pre-2026 rule, unchanged.',20,'2011-06-14','2025-12-31',1),(8,'NG','NHF','National Housing Fund contribution','percent_of',0.000,0.000000,NULL,'CONTRIB:NHF','annual',0,NULL,'Pre-2026: NHF was mandatory for employees earning above the threshold.',30,'2011-06-14','2025-12-31',1),(9,'GH','SSNIT','SSNIT employee contribution','percent_of',0.000,0.000000,NULL,'CONTRIB:SSNIT','monthly',0,NULL,'UNVERIFIED starting point — employee SSNIT is deducted before PAYE in Ghana.',10,'2024-01-01',NULL,1);
